"""Scoped static reader and exact evidence export for the measured13row study."""
import gzip
import hashlib
import json
import shutil
import time
import zipfile
from pathlib import Path
from induction_receptors_export import esc,math
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).resolve().parent;OUT=ROOT/'.gcts-active/commutativity13-20261011';DOC=ROOT/'docs/research/gcts-rl-renewal'

def load(p):
    if p.suffix=='.gz':
        with gzip.open(p,'rt') as f:return json.load(f)
    return json.loads(p.read_text())
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(v)+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def sec(v):return f'{v:,.3f}'

def cluster(raw,static):
    inventory={tuple(p['key']):p for p in raw['model']['placements']};keys=[tuple(k) for k in static['bindings'][0]];parts=[]
    for k in keys:
        p=inventory[k];role=['C','G','I1','I2'][k[1]];mark=[]
        for point,value in p['marks']:
            kind='mode' if point[1]==90 else 'command' if point[1]==1 else 'formula' if point[1]==0 else 'source'
            mark.append('<span class="mark '+kind+'"><code>'+esc(str(point)+': '+str(value))+'</code></span>')
        parts.append('<article class="tile"><strong>Row '+str(k[0]+1)+' <code>'+role+'</code></strong><p><code>'+esc(k)+'</code></p>'+''.join(mark)+'<details><summary>Exact scalar tile</summary><pre>'+esc(json.dumps(p,indent=2))+'</pre></details></article>')
    roots=[inventory[k] for k in keys if k[1]==1]
    formulas=''.join('<p>Row '+str(p['slot']+1)+' output: '+math(p['command']['formula'])+'</p>' for p in roots)
    required=[r for k in keys for r in inventory[k]['requirements']]
    receptors=''.join('<li>Requires row '+str(src+1)+' to carry '+math(f)+'.</li>' for src,f in required)
    return '<p>This is the first canonical inventory binding, a compatible eight-placement cluster with an external receptor. It is a visual inventory example, not a discovered commutativity proof or a seed for search.</p>'+formulas+'<div class="tiles">'+''.join(parts)+'</div><ul>'+receptors+'</ul>'

def main():
    began=time.perf_counter();producer=load(OUT/'preflight-summary.json');failed=load(OUT/'preflight-audit.json');repair=load(OUT/'preflight-audit-v2.json');cross=load(OUT/'external-model-correspondence.json');search=load(OUT/'search-summary.json');audit=load(OUT/'tree-audit-stream.json');execution=load(OUT/'execution-freeze.json')
    if search['status']!='complete_four_matched13_search_observations_pending_independent_audit' or audit['status']!='passed_complete_four13row_graph_and_proposal_traces':raise ValueError('complete bounded observations and independent every-node audit required')
    if repair['status']!='passed_complete_exact_proposer_serialization_and13model_preflight':raise ValueError('repaired preflight gate')
    plans=['preflight-plan.json','preflight-audit-plan.json','preflight-audit-plan-v2.json','external-model-correspondence-plan.json','execution-freeze.json','tree-audit-plan-stream.json'];bindings={}
    for name in plans:
        plan=load(OUT/name)
        for p,v in {**plan['source_sha256'],**plan['input_sha256']}.items():
            if h(ROOT/p)!=v:raise ValueError('unchanged freeze at export '+p)
            if p in bindings and bindings[p]!=v:raise ValueError('conflicting immutable source/input '+p)
            bindings[p]=v
    raw=load(OUT/'model13.json.gz');static=load(OUT/'static13.json.gz')
    observations=search['observations'];same=all(v['exact_structural_equal_to_base'] for v in audit['observations']);events=sum(v['policy_events'] for v in audit['observations']);nodes=sum(v['nodes'] for v in audit['observations'])
    if not same:raise ValueError('reader interpretation requires measured equalstructural traces')
    prior_export=load(OUT/'integration-receipt.json')
    data=dict(prior_view_export_receipt=prior_export,status='complete_audited_matched13row_unknowns',target=execution['case']['target'],theory=execution['case']['theory'],
              preflight_producer=producer,preflight_memory_unknown=failed,preflight_lifetime_repair=repair,external_model_correspondence=cross,
              search_producer=search,full_tree_audit=audit,source_and_input_sha256=bindings,
              claims=dict(gcts_found_proof=False,whole_native_target_queries=0,rl_training=False,exact_structural_equal=same,nodes=nodes,policy_events=events),
              costs=dict(manual_infrastructure_seconds='unmeasured',prior_grammar_native_admission='Reused exactcomplete94registry, with earlier measured coldproduction/replay and preparationunknowns preserved in prior reports. No zero-cost preparation claim.'))
    rows=[(v['id'],v['status'],v['metrics']['attempts'],v['metrics']['nodes'],sec(v['search_seconds']),sec(v['proposal_seconds']),sec(v['trace_serialization_seconds']),sec(v['process_seconds']),f"{v['peak_rss_bytes']:,}") for v in observations]
    costs=[('All 589 old-context correspondence producer',sec(producer['seconds']),f"{producer['peak_rss_bytes']:,}",'Complete; old proposal 91.631 s versus indexed 12.921 s on identical contexts'),
           ('First independent complete preflight',sec(failed['seconds']),f"{failed['peak_rss_bytes']:,}",'Unknown memory; 67,764,224-byte overshoot'),
           ('Versioned lifetime-only full preflight repair',sec(repair['seconds']),f"{repair['peak_rss_bytes']:,}",'Passed; cumulative failed + repaired 117.441 s'),
           ('Exact external 13-row model comparison',sec(cross['seconds']),f"{cross['peak_rss_bytes']:,}",'All schema fields equal; cumulative preflight audit 118.381 s'),
           ('Four fresh matched 13-row producer',sec(search['seconds']),'346685440 maximumchildRSS','Complete; four 5,000-attempt unknowns, all setup/serialization included'),
           ('Independent everyactualgraph/event replay',sec(audit['seconds']),f"{audit['peak_rss_bytes']:,}",str(nodes)+' nodes / '+str(events)+' policy events; passed'),
           ('Initial view/evidence export',sec(prior_export['exporter_seconds_including_full_zip_readback']),'Not separately sampled','Preserved earlier view; v2 improves labels and excludes its live export log'),
           ('Native commutativity whole query','0','Not executed','No GCTS candidate found; no capacity/native query authorized or run')]
    doc=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Matched 13-row GCTS cluster study</title><link rel="stylesheet" href="report.css"><script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']}};</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><style>main{max-width:1150px;margin:auto;padding:24px}nav{display:flex;gap:16px;flex-wrap:wrap}section{margin:36px 0}.unknown{background:#fff3dc;border-left:4px solid #b78322;padding:18px}.passed{background:#eaf5ed;border-left:4px solid #318363;padding:18px}.scroll{overflow-x:auto}table{border-collapse:collapse}td,th{padding:9px;border:1px solid #ccd;vertical-align:top}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.tile{padding:12px;border:2px solid #52627a;background:#f5f7fa;border-radius:6px}.mark{display:block;padding:5px;margin:4px 0;color:white;border-radius:4px}.command{background:#7253a7}.formula{background:#227c9c}.mode{background:#946a14}.source{background:#24765d}pre{white-space:pre-wrap;overflow-wrap:anywhere}details{margin:12px 0}.pin{overflow-wrap:anywhere}.legend{display:flex;gap:16px;flex-wrap:wrap}.legend span{padding:7px;color:white;border-radius:4px}.plot{margin:24px 0;min-width:900px}.plot .bar{font-size:14px;white-space:nowrap}.bar{height:28px;display:flex;align-items:center;color:white;padding:0 8px;background:#7253a7;margin:8px 0;max-width:100%;box-sizing:border-box}</style></head><body><main><p><a href="index.html#goals">Research program</a> · <a href="commutativity_cluster_results.html#result">Earlier 12-row unknowns</a> · <a href="commutativity_admissions.html#result">Complete admitted inventory</a></p><h1>Matched 13-row GCTS cluster study</h1><nav><a href="#result">Outcome</a><a href="#correspondence">Exact acceleration</a><a href="#searches">Four searches</a><a href="#reader">Colored inventory</a><a href="#costs">All costs</a><a href="#evidence">Exact evidence</a></nav>'''
    # Raw HTML keeps literal MathJax delimiter backslashes; JS needs two per delimiter.
    doc=doc.replace("['\\\\\\\\(','\\\\\\\\)']","['\\\\(','\\\\)']").replace("['\\\\\\\\[','\\\\\\\\]']","['\\\\[','\\\\]']")
    doc+='<section id="result"><h2>Faster implementation, unchanged unsuccessful ordering</h2><p class="unknown">All four fresh 13-row searches reached 5,000 attempts and remain unknown. No proof word was found, and no whole native target query was executed. The fixed cluster policy and the base search visited exactly the same structural tree: every recorded state hash, decision, complete alternative list and visited child key agrees. Fixed proposals add about 12.4 seconds per observation without changing these selected placements.</p><p>The query is '+math(execution['case']['target'])+'. This is a new 13-row boundary, preserving the exact original recursive-addition/induction theory, all 153 inference templates and all 94 independently admitted definitions. It is separate from the earlier 12-row unknowns and the earlier ordinary 13-line candidate.</p><p class="passed">The implementation improvement is independently measured: all 589 earlier proposal events preserve their full pools, canonical order, features, scores, ties and work counters. Every one of the 20,004 new search nodes and 1,054 fixed policy events passed complete independent graph replay. This is evidence for an exact cost optimization and a negative result for the present authored ordering, with no RL or proof-discovery claim.</p></section>'
    timing=producer['correspondence_timings'];ratio=timing['old_join_seconds']/timing['fast_join_seconds']
    doc+='<section id="correspondence"><h2>Exact proposal correspondence</h2><p>On all 589 identical earlier contexts, the old proposal routine took '+sec(timing['old_join_seconds'])+' seconds and the indexed routine took '+sec(timing['fast_join_seconds'])+' seconds, a measured ratio of '+sec(ratio)+'. This comparison uses one warming 12-row cache; it does not estimate the cold 13-row search cost. Feature evaluation took '+sec(timing['old_features_seconds'])+' and '+sec(timing['fast_features_seconds'])+' seconds respectively.</p><div class="scroll"><div class="plot" aria-label="Old versus exact indexed proposal seconds"><div class="bar" style="width:100%">Old: '+sec(timing['old_join_seconds'])+' s</div><div class="bar" style="width:'+str(100/ratio)+'%;background:#24765d">Indexed: '+sec(timing['fast_join_seconds'])+' s</div></div></div><p>The optimizer precomputes all compatible family bindings and their point incidence, caches exact canonical key words and bounded full-universe SHA rankings, and computes common row features once per event. Filtering a static ranking to the actual legal set preserves the old order. The 16-anchor LRU bounds retained ranks. Pools, validation counters, score semantics and every fallback remain exact; even the historical 48-unit growth-feature denominator is preserved at the new boundary.</p><p>The full independent comparison checks all 589 old recorded event contexts, every feature and deterministic score/tie decision, all 19,848 placements, all 18,480 compatible family bindings and four complete 41-node old/new diagnostic trees. The diagnostic fixtures alone have limited backtracking coverage; the actual target traces supply complete failed-child and rollback evidence.</p><p>Node-aware CJSON serialization retains every census, scalar, event and child. Standard JSON parsing verifies complete fixture values; complete actual graph replay validates every later trace. It avoids repeated Python generator writes for each scalar. Earlier source bytes and traces remain untouched.</p></section>'
    doc+='<section id="searches"><h2>Matched models and budgets</h2>'+table(['Run','Outcome','Attempts','Nodes','Search s','Proposal s','Trace serialization s','Whole process s','Peak RSS bytes'],rows)+'<p>The balanced order was base-r1, fixed-r1, fixed-r2, base-r2. Each used a fresh process/model and cold proposal cache, the same 13-row region, 5,000-attempt and 60-second search ceilings, and 512 MiB host bound. All four reached the attempt ceiling; none hit its wall or memory ceiling. The whole producer took '+sec(search['seconds'])+' seconds under its separate 300-second ceiling. Per-process seconds include source/input validation, model setup and complete output serialization.</p><p>Cold static-index initialization cost about 0.05 seconds per run and is included in search seconds. SHA-rank caches warm only within each observation. No ordinary proof word, induction choice, closure ranks, target witnesses or post-search certificate compaction were used to seed, order or train GCTS. The two base repetitions and two deterministic fixed repetitions are repeatability checks, not four stochastic samples.</p><p>All four audited structural projections are byte-identical to the base-r1 projection, with SHA-256 <code class="pin">'+esc(audit['observations'][0]['structural_sha256'])+'</code>. Policy metadata differs and was audited separately: each fixed run started 527 hints, recorded 11 eligible, 355 waiting, 1,143 invalid and 460 completed hint observations. Hints can complete through globally forced moves without selecting a different branch.</p><p>The exact full semantic model hash is <code class="pin">'+esc(producer['complete_model_sha256'])+'</code>, shared with the independently constructed external point control. That control has separate solver outcomes and authority. Fixed weights here are authored; no compatible policy was trained. The predeclared worst-case four-search allocation left too little assured room for training plus a comparable learned lane, so that lane was omitted before observations.</p></section>'
    doc+='<section id="reader"><h2>Inspect an actual inventory cluster and its colored markings</h2><p>The model has 52 required points: four fixed-orientation roles per proof row. Occupancy is '+r'\(t=1\)'+' represented by 12 integer units; exact catalog scalars bind complete formula/command words. Extended markings connect source inputs to earlier formula points. These high-level scalar point tiles are translated, not rotated. A primitive Wang-square occupancy embedding is not claimed.</p><div class="legend"><span class="command">Command layer</span><span class="formula">Formula layer</span><span class="mode">Interface-mode layer</span><span class="source">Source-index layer</span></div>'+cluster(raw,static)+'<p>All 42 family forms and every 18,480 row/source binding remain available. These families combine the two actually discovered derived lemmas with generic contextual rewrites; the 94 local interfaces remain authored infrastructure. A complete proof was not found, so this reader cannot present a new line-by-line commutativity proof. The earlier ordinary candidate remains inspectable in its own <a href="commutativity_cluster_results.html#reader">13-line reader</a>.</p></section>'
    doc+='<section id="costs"><h2>Preparation, failures and checking remain charged</h2>'+table(['Phase','Seconds','Peak RSS bytes','Outcome/scope'],costs)+'<p>The first independent preflight logically completed its comparisons but reached 604,635,136 bytes. Its 67,764,224-byte overshoot is a memory unknown. The separately frozen repair releases complete static/value witnesses before fixture replay and repeats every comparison at the same 512 MiB bound. Failed plus repaired audit cost is 117.441 seconds; including the separate exact external-model comparison gives 118.381 seconds within the original cumulative 300-second preflight-audit ceiling. No failed receipt, source or trace was overwritten.</p><p>The complete five-node grammar, pruning, 94 native admissions and their replay are reused from the exact earlier registry. Their cold costs, failed preparation attempts, prior search unknowns and earlier 596,873-cell ordinary-certificate capacity unknown remain in <a href="commutativity_admissions.html#costs">the admission report</a> and <a href="commutativity_cluster_results.html#costs">the earlier search report</a>. Manual infrastructure development is unmeasured. No native heap or microstep budget was enlarged in this study.</p><p>These bounded deterministic observations show that removing proposal overhead does not by itself improve the present proof ordering. They establish no nonprovability result, full Peano-arithmetic completeness, RL advantage or superiority over ordinary proof search.</p></section>'
    exports=[('preflight-plan.json','commutativity13_plan.json'),('preflight-summary.json','commutativity13_correspondence.json'),('preflight-audit.json','commutativity13_preflight_unknown.json'),('preflight-audit-v2.json','commutativity13_preflight_audit.json'),('execution-freeze.json','commutativity13_execution.json'),('search-summary.json','commutativity13_summary.json'),('tree-audit-plan-stream.json','commutativity13_tree_audit_plan.json'),('tree-audit-stream.json','commutativity13_tree_audit.json'),('external-model-correspondence.json','commutativity13_model_correspondence.json'),('binding13.json.gz','commutativity13_model.json.gz'),('static13.json.gz','commutativity13_inventory.json.gz')]
    doc+='<section id="evidence"><h2>Exact frozen evidence</h2><p><a href="commutativity13_reader_data_v2.json">Reader data and every reused binding</a> · <a href="commutativity13_evidence_v2.zip">Complete new evidence/source ZIP</a></p><ul>'+''.join('<li><a href="'+target+'">'+esc(source)+'</a></li>' for source,target in exports)+'</ul><p>The evidence ZIP preserves all new models, full trees/events, structural byte projections, every frozen source/input plan, both preflight-audit versions, all costs and source snapshots. Earlier exact inputs are listed by SHA-256 and remain in their existing immutable public exports. The whole target has zero native queries in this study.</p></section></main></body></html>'
    file=DOC/'commutativity13_v2.html';file.write_text(doc)
    (DOC/'commutativity13_reader_data_v2.json').write_text(json.dumps(data,indent=2)+'\n')
    files=[file,DOC/'commutativity13_reader_data_v2.json']
    for source,target in exports:shutil.copyfile(OUT/source,DOC/target);files.append(DOC/target)
    new_sources=sorted(HERE.glob('commutativity13_*.py'));files.extend(new_sources)
    archive=DOC/'commutativity13_evidence_v2.zip';members=[]
    inputs=[p for p in OUT.iterdir() if p.is_file() and p.name not in ('integration.json','integration-receipt.json','integration-v2.json','integration-receipt-v2.json','report-v2.log')]
    inputs+=new_sources
    inputs+=[ROOT/p for p in bindings if p.startswith('.gcts-active/external-point-commutativity-20261011/')]
    with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted(set(inputs)):
            name=str(p.relative_to(ROOT));z.write(p,name);members.append(dict(path=name,sha256=h(p),bytes=p.stat().st_size))
    files.append(archive)
    manifest=dict(prior_view_export_manifest_sha256=h(OUT/'integration.json'),status='frozen_audited_matched13row_search_export',files=[dict(path=str(p.relative_to(ROOT)),sha256=h(p),bytes=p.stat().st_size) for p in files],
                  archive_members=members,reused_input_sha256={p:v for p,v in bindings.items() if not p.startswith(str(OUT.relative_to(ROOT))+'/')},
                  evidence_zip_sha256=h(archive),reader='docs/research/gcts-rl-renewal/commutativity13_v2.html#result',target_proofs_found=0,whole_native_target_queries=0)
    (OUT/'integration-v2.json').write_text(json.dumps(manifest,indent=2)+'\n')
    for v in manifest['files']:
        p=ROOT/v['path']
        if h(p)!=v['sha256'] or p.stat().st_size!=v['bytes']:raise ValueError('exact public manifest binding')
    with zipfile.ZipFile(archive) as z:
        if len(z.namelist())!=len(members):raise ValueError('complete archive count')
        for v in members:
            b=z.read(v['path'])
            if hashlib.sha256(b).hexdigest()!=v['sha256'] or len(b)!=v['bytes']:raise ValueError('exact evidence ZIP bytes')
    receipt=dict(status='passed_complete_immutable_export_binding',integration_sha256=h(OUT/'integration-v2.json'),public_files=len(files),archive_members=len(members),
                 exporter_seconds_including_full_zip_readback=time.perf_counter()-began,reader_uses_chtml=True,native_queries=0,all_original_freezes_unchanged=True)
    (OUT/'integration-receipt-v2.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt),flush=True)

if __name__=='__main__':main()
